import { useState, useEffect, useRef } from 'react'
import { supabase } from '../supabaseClient'

const CLINICIANS_LIST = [
  'Dr. José Antonio García, PsyD — Lic. 7159',
  'Dra. Adrianna Ortiz Morales, PhD — Lic. 7403',
]
const SESSION_TYPES = ['Individual','Pareja','Familiar','Grupal','Evaluación','Consulta','Telehealth']
const MODALITIES   = ['Presencial','Telehealth – Video','Telehealth – Teléfono']
const CPT_CODES    = ['90791 – Evaluación psiquiátrica','90834 – Psicoterapia 45 min','90837 – Psicoterapia 60 min','90847 – Psicoterapia familiar','90853 – Psicoterapia grupal','96130 – Pruebas psicológicas']
const TECNICAS     = ['TCC','ACT','DBT','EMDR','Psicodinámico','Mindfulness','Psicoeducación','Activación conductual','Narrativa','Terapia de juego','Gestalt','Sistémica','Entrevista motivacional']
const AFECTOS      = ['Eutímico','Deprimido','Ansioso','Lábil','Plano','Elevado']
const INSURE       = ['','MCS','Triple S','Privado / Pago directo','Psicología Para Todos','Otro']
const DIAGS        = ['F32.1 – Ep. depresivo mayor, moderado','F32.9 – Ep. depresivo mayor, no especificado','F41.0 – T. de pánico','F41.1 – T. ansiedad generalizada','F43.10 – TEPT','F43.23 – T. adaptativo mixto','F90.0 – TDAH inatento','F90.2 – TDAH combinado','F60.3 – T. limítrofe personalidad','F31.9 – T. bipolar']
const FREQUENCIES  = ['Semanal','Cada dos semanas','Mensual','Según necesidad','Alta – sin próxima cita']
const RISK_LEVELS  = ['Ninguno','Bajo','Moderado','Alto','Inminente']

function todayStr() { return new Date().toISOString().split('T')[0] }
const gafLabel = v => { if(v>=91)return'Excelente'; if(v>=81)return'Mínimos'; if(v>=71)return'Leves'; if(v>=61)return'Mod. leve'; if(v>=51)return'Moderados'; if(v>=41)return'Serio'; if(v>=31)return'Marcado'; return'Severo' }
const riskBg   = {'Ninguno':'#E1F5EE','Bajo':'#EAF3DE','Moderado':'#FAEEDA','Alto':'#FCEBEB','Inminente':'#E24B4A'}
const riskClr  = {'Ninguno':'#0F6E56','Bajo':'#3B6D11','Moderado':'#854F0B','Alto':'#A32D2D','Inminente':'#fff'}

const emptyNote = {
  patient_name:'', clinician:'', session_type:'', modality:'', enc_date: todayStr(),
  time_start:'', time_end:'', duration_min:'', session_num:'', record_num:'', insurance:'', cpt_code:'', diagnosis:'',
  apariencia:[], actitud:[], mood:'', afecto:'', pensamiento:[], orientacion:[], mse_notes:'',
  gaf_score:65, risk_suicida:'Ninguno', risk_homicida:'Ninguno', safety_plan:'',
  session_topics:'', tecnicas:[], resp_interv:'', progreso:'', cambios:[], homework:'',
  next_appt:'', frequency:'', extra_notes:'', status:'draft', signed_by:'', signed_at:null,
}

const toArr = val => {
  if (Array.isArray(val)) return val
  if (!val || val === '') return []
  return val.split(', ').filter(Boolean)
}

export default function NoteForm({ nav, session, patient, note }) {
  const [form, setForm] = useState(() => {
    if (note?.id) return {
      ...emptyNote, ...note,
      apariencia:  toArr(note.apariencia),
      actitud:     toArr(note.actitud),
      pensamiento: toArr(note.pensamiento),
      orientacion: toArr(note.orientacion),
      tecnicas:    toArr(note.tecnicas),
      cambios:     toArr(note.cambios),
      mood: note.mood || '', mse_notes: note.mse_notes || '',
      session_topics: note.session_topics || '', resp_interv: note.resp_interv || '',
      homework: note.homework || '', safety_plan: note.safety_plan || '',
      extra_notes: note.extra_notes || '', progreso: note.progreso || '', afecto: note.afecto || '',
    }
    const base = { ...emptyNote }
    if (patient) {
      base.patient_name = patient.name || ''
      base.insurance    = patient.insurance || ''
      base.diagnosis    = patient.diagnosis || ''
      base.record_num   = patient.record_num || ''
      base.clinician    = patient.clinician || ''
    }
    return base
  })

  const [patients, setPatients]     = useState([])
  const [saving, setSaving]         = useState(false)
  const [toast, setToast]           = useState(null)
  const [aiOpen, setAiOpen]         = useState(false)
  const [aiInput, setAiInput]       = useState('')
  const [aiMsgs, setAiMsgs]         = useState([{ role:'ai', text:'👋 Hola. Usa los botones ✦IA de cada sección o escríbeme directamente. Generaré el texto y podrás insertarlo con un clic.' }])
  const [aiLoading, setAiLoading]   = useState(false)
  const [apiKey, setApiKey]         = useState(() => localStorage.getItem('cpc_api_key') || '')
  const [showKeyInput, setShowKeyInput] = useState(false)
  const msgsRef = useRef(null)

  useEffect(() => {
    supabase.from('patients').select('id,name,insurance,diagnosis,record_num,clinician,gender,pronouns').order('name').then(({data}) => setPatients(data||[]))
  }, [])

  useEffect(() => {
    if (msgsRef.current) msgsRef.current.scrollTop = msgsRef.current.scrollHeight
  }, [aiMsgs])

  const sf = (k, v) => setForm(f => ({ ...f, [k]: v }))
  const toggleArr = (k, v) => sf(k, form[k].includes(v) ? form[k].filter(x=>x!==v) : [...form[k], v])
  const showToast = (msg, type='ok') => { setToast({msg,type}); setTimeout(()=>setToast(null),3000) }

  // ── TIME AUTO-CALC
  const onStartTime = (val) => {
    sf('time_start', val)
    if (!val) return
    const [sh, sm] = val.split(':').map(Number)
    const total = sh*60 + sm + 60
    const eh = String(Math.floor(total/60)%24).padStart(2,'0')
    const em = String(total%60).padStart(2,'0')
    sf('time_end', `${eh}:${em}`)
    sf('duration_min', 60)
  }
  const onEndTime = (val) => {
    sf('time_end', val)
    if (!val || !form.time_start) return
    const [sh,sm] = form.time_start.split(':').map(Number)
    const [eh,em] = val.split(':').map(Number)
    const diff = (eh*60+em) - (sh*60+sm)
    if (diff > 0) sf('duration_min', diff)
  }

  // ── PATIENT SELECT
  const onPatientChange = (val) => {
    sf('patient_name', val)
    const p = patients.find(x => x.name === val)
    if (p) {
      if (p.record_num) sf('record_num', p.record_num)
      if (p.insurance)  sf('insurance',  p.insurance)
      if (p.diagnosis)  sf('diagnosis',  p.diagnosis)
      if (p.clinician)  sf('clinician',  p.clinician)
    }
  }

  // ── CLEAR NOTE
  const clearNote = () => {
    if (window.confirm('¿Limpiar todos los campos para nueva nota?')) {
      setForm({...emptyNote})
      setAiMsgs([{ role:'ai', text:'🔄 Nota limpiada. Lista para nuevo paciente.' }])
    }
  }

  // ── SAVE
  const saveNote = async (status='draft') => {
    if (!form.patient_name.trim()) { showToast('Nombre del paciente requerido','err'); return }
    setSaving(true)
    const payload = {
      ...form,
      status,
      session_num:  form.session_num  ? parseInt(form.session_num)  : null,
      duration_min: form.duration_min ? parseInt(form.duration_min) : null,
      gaf_score:    form.gaf_score    ? parseInt(form.gaf_score)    : 65,
      tecnicas:    Array.isArray(form.tecnicas)    ? form.tecnicas.join(', ')    : form.tecnicas,
      apariencia:  Array.isArray(form.apariencia)  ? form.apariencia.join(', ')  : form.apariencia,
      actitud:     Array.isArray(form.actitud)      ? form.actitud.join(', ')     : form.actitud,
      pensamiento: Array.isArray(form.pensamiento)  ? form.pensamiento.join(', ') : form.pensamiento,
      orientacion: Array.isArray(form.orientacion)  ? form.orientacion.join(', ') : form.orientacion,
      cambios:     Array.isArray(form.cambios)      ? form.cambios.join(', ')     : form.cambios,
      next_appt:   form.next_appt  || null,
      updated_at:  new Date().toISOString(),
    }
    if (status === 'signed') {
      payload.signed_by  = form.clinician
      payload.signed_at  = new Date().toISOString()
    }
    let error
    if (form.id) {
      ({ error } = await supabase.from('progress_notes').update(payload).eq('id', form.id))
    } else {
      payload.created_by = session.user.id
      const { data, error: e } = await supabase.from('progress_notes').insert(payload).select().single()
      error = e
      if (data) sf('id', data.id)
    }
    setSaving(false)
    if (error) { showToast('Error: ' + error.message, 'err'); return }
    showToast(status === 'signed' ? '✓ Nota firmada y guardada.' : '💾 Guardado.')
  }

  // ── PRINT
  const printNote = () => {
    const ptCtx = patients.find(p => p.name === form.patient_name)
    const html  = generatePrintHTML(form, ptCtx)
    const win   = window.open('', '_blank', 'width=900,height=700')
    win.document.open()
    win.document.write(html)
    win.document.close()
    win.focus()
    setTimeout(() => win.print(), 800)
  }

  // ── AI
  const buildSystemPrompt = () => {
    const ptCtx = patients.find(p => p.name === form.patient_name)
    const pronRef = ptCtx?.pronouns === 'ella/le' || ptCtx?.gender === 'Femenino' ? 'la paciente'
      : ptCtx?.pronouns === 'él/le'  || ptCtx?.gender === 'Masculino' ? 'el paciente' : 'el/la paciente'
    return `Eres un asistente clínico de Caribbean Psychology Wellness Center. Redactas texto para notas de progreso clínico.

REGLAS ESTRICTAS:
- Responde SOLO en español clínico. SIN títulos, SIN encabezados, SIN markdown, SIN asteriscos.
- Escribe DIRECTAMENTE el texto del campo (2-4 oraciones), en tercera persona, usando "${pronRef}".
- Termina SIEMPRE con [CAMPO:id] al final. Usa guión bajo (ej: [CAMPO:mse_notes], [CAMPO:session_topics]).
- No agregues explicaciones antes ni después del texto.

Contexto: Paciente: ${form.patient_name||'N/E'} | Dx: ${form.diagnosis||'N/E'} | GAF: ${form.gaf_score} | Riesgo: ${form.risk_suicida} | Afecto: ${form.afecto||'N/E'} | Técnicas: ${Array.isArray(form.tecnicas)?form.tecnicas.join(', '):form.tecnicas||'N/E'} | Apariencia: ${Array.isArray(form.apariencia)?form.apariencia.join(', '):''} | Actitud: ${Array.isArray(form.actitud)?form.actitud.join(', '):''}`
  }

  const sendAI = async (promptOverride) => {
    const msg = promptOverride || aiInput.trim()
    if (!msg) return
    if (!apiKey) { setShowKeyInput(true); return }
    if (!aiOpen) setAiOpen(true)
    setAiInput('')
    setAiMsgs(m => [...m, { role:'user', text: msg.replace(/\[CAMPO:[^\]]+\]/g,'').trim() }])
    setAiLoading(true)
    try {
      const resp = await fetch('https://api.anthropic.com/v1/messages', {
        method: 'POST',
        headers: { 'Content-Type':'application/json', 'x-api-key':apiKey, 'anthropic-version':'2023-06-01', 'anthropic-dangerous-direct-browser-access':'true' },
        body: JSON.stringify({ model:'claude-sonnet-4-5', max_tokens:600, system: buildSystemPrompt(), messages:[{role:'user',content:msg}] })
      })
      const data = await resp.json()
      if (!resp.ok) {
        setAiMsgs(m => [...m, { role:'ai', text:'❌ ' + (data?.error?.message||'Error API') }])
        setAiLoading(false); return
      }
      const text = data.content?.[0]?.text || ''
      const fieldTag = extractFieldTag(text)
      const cleanText = text.replace(/\[CAMPO:[^\]]+\]/g,'').replace(/#{1,3}\s.+\n?/g,'').trim()
      setAiMsgs(m => [...m, { role:'ai', text: cleanText, fieldTag }])
    } catch(e) {
      setAiMsgs(m => [...m, { role:'ai', text:'⚠️ Error de conexión.' }])
    }
    setAiLoading(false)
  }

  const applyToField = (fieldTag, cleanText) => {
    if (!fieldTag) return
    const key = fieldTag.replace(/-/g,'_')
    if (Object.keys(emptyNote).includes(key)) {
      sf(key, cleanText)
      showToast('✓ Texto insertado.')
    } else {
      showToast('⚠ Campo no reconocido: ' + key)
    }
  }

  const quickAsk = (prompt) => {
    setAiOpen(true)
    setTimeout(() => sendAI(prompt), 100)
  }

  const extractFieldTag = (text) => {
    const m = text.match(/\[CAMPO:([a-z0-9_\-]+)\]/)
    return m ? m[1].replace(/-/g,'_') : null
  }

  // ── RENDER HELPERS
  const Sec = ({ num, title, aiPrompt, children }) => (
    <div style={{ background:'#fff', border:'1px solid #e2e6ec', borderRadius:12, marginBottom:12, overflow:'hidden' }}>
      <div style={{ display:'flex', alignItems:'center', justifyContent:'space-between', padding:'11px 16px', background:'#f7f8fa', borderBottom:'1px solid #e2e6ec' }}>
        <div style={{ fontSize:12, fontWeight:700, color:'#1a2c4e', textTransform:'uppercase', letterSpacing:'.06em' }}>{num}. {title}</div>
        {aiPrompt && (
          <button onClick={() => quickAsk(aiPrompt)}
            style={{ background:'#E1F5EE', border:'1px solid #9FE1CB', borderRadius:5, padding:'4px 10px', fontSize:11, color:'#0F6E56', cursor:'pointer', fontWeight:600, fontFamily:'inherit' }}>
            ✦ IA
          </button>
        )}
      </div>
      <div style={{ padding:'14px 16px' }}>{children}</div>
    </div>
  )

  const ChipGroup = ({ label, opts, value, multi, stateKey }) => (
    <div>
      <label style={s.lbl}>{label}</label>
      <div style={{ display:'flex', flexWrap:'wrap', gap:6, marginTop:5 }}>
        {opts.map(o => {
          const active = multi ? value.includes(o) : value === o
          return (
            <button key={o} onClick={() => multi ? toggleArr(stateKey,o) : sf(stateKey, active?'':o)}
              style={{ padding:'5px 11px', borderRadius:6, border:`1px solid ${active?'#1D9E75':'#e2e6ec'}`, background:active?'#E1F5EE':'#fff', color:active?'#0F6E56':'#666', fontSize:12.5, cursor:'pointer', fontFamily:'inherit' }}>
              {o}
            </button>
          )
        })}
      </div>
    </div>
  )

  const TextArea = ({ stateKey, label, placeholder, aiPrompt }) => (
    <div style={{ marginTop:10 }}>
      <div style={{ display:'flex', alignItems:'center', justifyContent:'space-between', marginBottom:4 }}>
        <label style={s.lbl}>{label}</label>
        {aiPrompt && (
          <button onClick={() => quickAsk(aiPrompt)}
            style={{ background:'#E1F5EE', border:'1px solid #9FE1CB', borderRadius:4, padding:'2px 8px', fontSize:10, color:'#0F6E56', cursor:'pointer', fontFamily:'inherit' }}>
            ✦ IA
