          <div style={{ display:'grid', gridTemplateColumns:'1fr 1fr', gap:'10px 14px' }}>
            <ChipGroup label="Apariencia" opts={['Apropiada','Bien arreglada','Descuidada','Inapropiada']} value={form.apariencia} multi stateKey="apariencia" />
            <ChipGroup label="Actitud / Comportamiento" opts={['Cooperador','Ansioso','Resistente','Agitado','Retraído','Hostil']} value={form.actitud} multi stateKey="actitud" />
            <div>
              <label style={s.lbl}>Estado de ánimo (autoreportado)</label>
              <input style={{ ...s.inp, marginTop:5 }} value={form.mood||''} onChange={e=>sf('mood',e.target.value)} placeholder='"me siento triste y cansado"' />
