            <ChipGroup label="Pensamiento / Cognición" opts={['Lógico y coherente','Desorganizado','Ideas rumiativas','Pensamiento mágico','Alucinaciones','Delusiones']} value={form.pensamiento} multi stateKey="pensamiento" />
            <ChipGroup label="Orientación / Insight" opts={['Orientado ×3','Insight adecuado','Juicio intacto','Memoria intacta','Concentración ↓','Insight limitado']} value={form.orientacion} multi stateKey="orientacion" />
          </div>
          <TextArea stateKey="mse_notes" label="Observaciones narrativas del estado mental"
            placeholder="Descripción narrativa del estado mental..."
            aiPrompt="Redacta la narrativa del estado mental en 3 oraciones clínicas. [CAMPO:mse_notes]" />
        </Sec>

        {/* SEC 4 — GAF */}
        <Sec num={4} title="Funcionalidad Global (GAF)">
          <div style={{ background:'#f7f8fa', borderRadius:10, padding:'14px 16px' }}>
            <div style={{ display:'flex', justifyContent:'space-between', alignItems:'flex-start', marginBottom:10 }}>
