                  <button key={r} onClick={()=>sf('risk_suicida',r)}
                    style={{ padding:'6px 11px', borderRadius:6, border:`1.5px solid ${form.risk_suicida===r?(riskBg[r]):'#e2e6ec'}`, background:form.risk_suicida===r?riskBg[r]:'#fff', color:form.risk_suicida===r?riskClr[r]:'#666', fontSize:12, fontWeight:500, cursor:'pointer', fontFamily:'inherit' }}>{r}</button>
                ))}
