          <div style={{ display:'grid', gridTemplateColumns:'1fr 1fr', gap:'10px 14px' }}>
            <ChipGroup label="Progreso hacia objetivos" opts={['Notable mejoría','Mejoría moderada','Sin cambios','Deterioro leve','Deterioro significativo','No aplica (1ra sesión)']} value={form.progreso} stateKey="progreso" />
            <ChipGroup label="Cambios al plan" opts={['Sin cambios','Ajuste de frecuencia','Nuevo objetivo','Referido psiquiatría','Referido otro especialista','Alta clínica']} value={form.cambios} multi stateKey="cambios" />
          </div>
          <TextArea stateKey="homework" label="Tareas / Asignaciones para el paciente"
