              <div style={{ borderBottom:'1.5px solid #1a2c4e', padding:'4px 0', minHeight:32, fontSize:13, color:'#1a2c4e', fontWeight:500, display:'flex', alignItems:'flex-end' }}>
                {form.signed_by || form.clinician || '—'}
              </div>
