            </div>
            <div>
              <div style={s.lbl}>Fecha de la nota</div>
              <div style={{ borderBottom:'1.5px solid #1a2c4e', padding:'4px 0', minHeight:32, fontSize:13, color:'#1a2c4e', display:'flex', alignItems:'flex-end' }}>
