            {aiMsgs.map((m,i)=>(
              <div key={i} style={{ display:'flex', flexDirection:'column', alignItems:m.role==='user'?'flex-end':'flex-start' }}>
                <div style={{ padding:'8px 11px', borderRadius:9, fontSize:12.5, lineHeight:1.6, maxWidth:'94%', background:m.role==='user'?'#1a2c4e':'#f0f2f5', color:m.role==='user'?'#fff':'#1a2c4e', whiteSpace:'pre-wrap' }}>
                  {m.text}
                </div>
                {m.fieldTag && (
                  <button onClick={() => applyToField(m.fieldTag, m.text)}
                    style={{ marginTop:4, background:'#1D9E75', border:'none', color:'#fff', borderRadius:5, padding:'4px 12px', fontSize:11.5, fontWeight:600, cursor:'pointer', fontFamily:'inherit' }}>
                    ✅ Insertar en nota
                  </button>
                )}
                <div style={{ fontSize:9.5, color:'#9aa3b2', marginTop:2 }}>{m.role==='user'?'Tú':'Claude · CPC'}</div>
              </div>
            ))}
            {aiLoading && <div style={{ fontSize:12, color:'#9aa3b2', textAlign:'center', padding:8 }}>⏳ Generando...</div>}
          </div>
          <div style={{ padding:'6px 10px', borderTop:'1px solid #e2e6ec', display:'flex', flexWrap:'wrap', gap:4, flexShrink:0 }}>
            {[
              { label:'MSE narrativo',    prompt:'Redacta la narrativa del MSE en 3 oraciones. [CAMPO:mse_notes]' },
              { label:'Temas sesión',     prompt:'Redacta los temas abordados en 2 oraciones. [CAMPO:session_topics]' },
              { label:'Respuesta Px',     prompt:'Redacta la respuesta del paciente en 2 oraciones. [CAMPO:resp_interv]' },
              { label:'Tareas',           prompt:'Escribe 3 tareas terapéuticas breves. [CAMPO:homework]' },
              { label:'Plan seguridad',   prompt:'Redacta el plan de seguridad en 2 oraciones. [CAMPO:safety_plan]' },
              { label:'Revisar nota',     prompt:'Revisa los campos de texto y da sugerencias breves de mejora clínica.' },
            ].map(({label,prompt}) => (
              <button key={label} onClick={() => sendAI(prompt)}
                style={{ background:'#f7f8fa', border:'1px solid #e2e6ec', borderRadius:12, padding:'4px 9px', fontSize:11, cursor:'pointer', fontFamily:'inherit', color:'#5a6478' }}>
                {label}
              </button>
            ))}
          </div>
          {showKeyInput && (
            <div style={{ padding:'10px 12px', background:'#FAEEDA', borderTop:'1px solid #FAC775', flexShrink:0 }}>
              <div style={{ fontSize:11.5, color:'#854F0B', marginBottom:6 }}>🔑 API Key de Anthropic:</div>
              <div style={{ display:'flex', gap:6 }}>
                <input style={{ flex:1, fontSize:12, padding:'6px 8px', border:'1px solid #e2e6ec', borderRadius:6 }}
                  placeholder="sk-ant-..." defaultValue={apiKey}
                  onChange={e=>setApiKey(e.target.value)} />
                <button onClick={()=>{localStorage.setItem('cpc_api_key',apiKey);setShowKeyInput(false);showToast('✓ API Key guardada.')}}
                  style={{ background:'#1D9E75', color:'#fff', border:'none', borderRadius:6, padding:'6px 10px', fontSize:12, cursor:'pointer' }}>Guardar</button>
              </div>
            </div>
          )}
          <div style={{ padding:'8px 10px', borderTop:'1px solid #e2e6ec', display:'flex', gap:6, alignItems:'flex-end', flexShrink:0 }}>
            <textarea value={aiInput} onChange={e=>setAiInput(e.target.value)}
              onKeyDown={e=>{ if(e.key==='Enter'&&!e.shiftKey){e.preventDefault();sendAI()} }}
              placeholder="Escribe aquí..." rows={2}
              style={{ flex:1, fontSize:12.5, padding:'7px 9px', border:'1.5px solid #1D9E75', borderRadius:7, resize:'none', fontFamily:'inherit', outline:'none' }} />
            <button onClick={()=>sendAI()} disabled={aiLoading}
              style={{ background:'#1D9E75', color:'#fff', border:'none', borderRadius:7, padding:'10px 13px', cursor:'pointer', fontSize:15 }}>➤</button>
          </div>
        </div>
      )}

      {toast && <div style={{ position:'fixed', bottom:20, right:20, background:toast.type==='err'?'#E24B4A':'#1D9E75', color:'#fff', padding:'10px 18px', borderRadius:8, fontSize:13, fontWeight:500, zIndex:999 }}>{toast.msg}</div>}
    </div>
  )
}

const s = {
  lbl: { fontSize:11, fontWeight:600, color:'#9aa3b2', textTransform:'uppercase', letterSpacing:'.07em', display:'block', marginBottom:4 },
  inp: { width:'100%', padding:'8px 10px', border:'1px solid #e2e6ec', borderRadius:8, fontSize:13, fontFamily:'inherit', outline:'none', boxSizing:'border-box' },
  btn: { padding:'8px 14px', borderRadius:8, border:'1px solid #e2e6ec', fontSize:13, fontWeight:500, cursor:'pointer', fontFamily:'inherit', background:'#fff' },
}

// ── PRINT HTML
function generatePrintHTML(form, ptCtx) {
  const arr = v => Array.isArray(v) ? v.filter(Boolean).join(' · ') : (v||'')
  const has = v => v && String(v).trim()
  const gLabel = v => { if(v>=91)return'Excelente'; if(v>=81)return'Mínimos'; if(v>=71)return'Leves'; if(v>=61)return'Mod. leve'; if(v>=51)return'Moderados'; if(v>=41)return'Serio'; if(v>=31)return'Marcado'; return'Severo' }
  const riskColor = {'Ninguno':'#0F6E56','Bajo':'#3B6D11','Moderado':'#854F0B','Alto':'#A32D2D','Inminente':'#fff'}
  const riskBgMap = {'Ninguno':'#E1F5EE','Bajo':'#EAF3DE','Moderado':'#FAEEDA','Alto':'#FCEBEB','Inminente':'#E24B4A'}
  const rs = form.risk_suicida||'Ninguno', rh = form.risk_homicida||'Ninguno'
  const f = (label, value) => has(value) ? `<div class="field"><span class="fl">${label}</span><span class="fv">${value}</span></div>` : ''
  const sh = (n, title) => `<div class="sh"><span class="sn">${n}</span>${title}</div>`
  const chips = str => str ? str.split(' · ').map(t=>`<span class="chip">${t}</span>`).join('') : ''

  return `<!DOCTYPE html><html lang="es"><head><meta charset="UTF-8">
  <title>Nota · ${form.patient_name||'Paciente'}</title>
  <style>
    @page { size: letter portrait; margin: 14mm 15mm 12mm; }
    * { box-sizing: border-box; margin: 0; padding: 0; }
    body { font-family: 'Calibri', Arial, sans-serif; font-size: 8.2pt; color: #1e2530; }
    .header { display: flex; justify-content: space-between; align-items: flex-end; padding-bottom: 7pt; margin-bottom: 7pt; border-bottom: 2.5pt solid #1a2c4e; }
    .logo { display: flex; align-items: center; gap: 9pt; }
    .logo-dot { width: 30pt; height: 30pt; border-radius: 50%; background: #1a2c4e; color: #fff; font-size: 9.5pt; font-weight: 700; display: flex; align-items: center; justify-content: center; flex-shrink: 0; }
    .clinic-n { font-size: 12pt; font-weight: 700; color: #1a2c4e; }
    .clinic-s { font-size: 7pt; color: #9aa3b2; margin-top: 1pt; }
    .hdr-right { text-align: right; }
    .doc-t { font-size: 11pt; font-weight: 700; color: #1D9E75; }
    .doc-s { font-size: 7pt; color: #9aa3b2; margin-top: 2pt; }
    .hipaa { display: inline-block; font-size: 6pt; font-weight: 700; background: #FCEBEB; color: #A32D2D; padding: 1.5pt 5pt; border-radius: 3pt; margin-top: 3pt; }
    .pt-strip { background: #1a2c4e; border-radius: 5pt; padding: 6pt 10pt; margin-bottom: 7pt; display: flex; justify-content: space-between; align-items: center; }
    .pt-n { font-size: 11.5pt; font-weight: 700; color: #fff; }
    .pt-m { font-size: 7.5pt; color: #9ab0cc; margin-top: 2pt; display: flex; gap: 10pt; flex-wrap: wrap; }
    .pt-dx { font-size: 8pt; color: #9FE1CB; text-align: right; max-width: 180pt; }
    .cols { display: grid; grid-template-columns: 1fr 1fr; gap: 0 14pt; }
    .sec { margin-bottom: 6pt; }
    .sh { display: flex; align-items: center; gap: 5pt; margin-bottom: 3pt; padding-bottom: 1.5pt; border-bottom: .8pt solid #1D9E75; font-size: 7pt; font-weight: 700; color: #1a2c4e; text-transform: uppercase; letter-spacing: .07em; }
    .sn { background: #1D9E75; color: #fff; font-size: 6pt; font-weight: 700; width: 11pt; height: 11pt; border-radius: 50%; display: inline-flex; align-items: center; justify-content: center; flex-shrink: 0; }
    .field { display: flex; gap: 4pt; margin-bottom: 1.5pt; align-items: baseline; }
    .fl { font-size: 7.5pt; font-weight: 700; color: #6b7280; min-width: 72pt; flex-shrink: 0; }
    .fv { font-size: 8pt; color: #1e2530; flex: 1; }
    .narr { background: #f7f9fc; border-left: 2pt solid #1D9E75; padding: 3pt 6pt; font-size: 8pt; line-height: 1.5; color: #2d3748; margin: 2pt 0 3pt; }
    .chips { display: flex; flex-wrap: wrap; gap: 2.5pt; margin: 2pt 0 3pt; }
    .chip { background: #E1F5EE; color: #0F6E56; padding: 1.5pt 6pt; border-radius: 10pt; font-size: 7pt; font-weight: 500; }
    .chip-b { background: #E6F1FB; color: #0C447C; }
    .gaf-row { display: flex; align-items: center; gap: 8pt; margin: 2pt 0; }
    .gaf-num { font-size: 22pt; font-weight: 700; color: #1a2c4e; line-height: 1; }
    .gaf-lbl { font-size: 8pt; font-weight: 700; color: #1D9E75; margin-bottom: 3pt; }
    .gaf-bar { height: 6pt; border-radius: 3pt; background: linear-gradient(to right, #E24B4A, #EF9F27 38%, #1D9E75 72%, #0F6E56); }
    .gaf-sc { display: flex; justify-content: space-between; font-size: 6pt; color: #9aa3b2; margin-top: 1.5pt; }
    .risk-row { display: flex; gap: 5pt; margin: 2pt 0; }
    .risk-box { flex: 1; border-radius: 4pt; padding: 4pt 6pt; text-align: center; }
    .risk-lbl { font-size: 6pt; font-weight: 600; text-transform: uppercase; opacity: .8; margin-bottom: 1.5pt; }
    .risk-val { font-size: 9pt; font-weight: 700; }
    .sig-wrap { display: grid; grid-template-columns: 1fr 1fr; gap: 12pt; margin: 5pt 0; padding: 6pt 10pt; background: #f7f9fc; border-radius: 5pt; }
    .sig-line { border-bottom: 1.5pt solid #1a2c4e; min-height: 20pt; padding-bottom: 2pt; font-size: 9pt; font-weight: 700; color: #1a2c4e; display: flex; align-items: flex-end; }
    .sig-sub { font-size: 6.5pt; color: #9aa3b2; text-transform: uppercase; margin-top: 2pt; }
    .cert { background: #E1F5EE; border: .5pt solid #9FE1CB; border-radius: 4pt; padding: 5pt 8pt; font-size: 7.5pt; color: #0F6E56; line-height: 1.55; margin: 4pt 0; }
    .footer { text-align: center; font-size: 6.5pt; color: #c8cdd6; margin-top: 4pt; padding-top: 4pt; border-top: .3pt solid #e2e6ec; }
    @media print { * { -webkit-print-color-adjust: exact !important; print-color-adjust: exact !important; } }
  </style></head><body>

  <div class="header">
    <div class="logo">
      <div class="logo-dot">CPC</div>
      <div><div class="clinic-n">Caribbean Psychology Wellness Center</div><div class="clinic-s">San Juan, Puerto Rico · caribbeanpsychology.com</div></div>
    </div>
    <div class="hdr-right">
      <div class="doc-t">Nota de Progreso Clínico</div>
      <div class="doc-s">${form.enc_date||''} · ${form.session_type||''} ${form.modality?'· '+form.modality:''} · Sesión ${form.session_num||'—'}</div>
      <div class="hipaa">Confidencial · HIPAA · Ley 408 PR</div>
    </div>
  </div>

  <div class="pt-strip">
    <div>
      <div class="pt-n">${form.patient_name||'—'}</div>
      <div class="pt-m">
        ${ptCtx?.gender?`<span>${ptCtx.gender}${ptCtx.pronouns?' · '+ptCtx.pronouns:''}</span>`:''}
        ${has(form.record_num)?`<span>Exp: ${form.record_num}</span>`:''}
        ${has(form.insurance)?`<span>${form.insurance}</span>`:''}
        ${has(form.cpt_code)?`<span>${form.cpt_code.split('–')[0].trim()}</span>`:''}
      </div>
    </div>
    ${has(form.diagnosis)?`<div class="pt-dx">${form.diagnosis}</div>`:''}
  </div>

  <div class="cols">
  <div>
    <div class="sec">${sh(1,'Encuentro')}${f('Clínico',form.clinician)}${f('Hora',has(form.time_start)&&has(form.time_end)?form.time_start+' – '+form.time_end+(form.duration_min?' ('+form.duration_min+' min)':''):null)}</div>
    <div class="sec">${sh(3,'Estado Mental')}${f('Apariencia',arr(form.apariencia))}${f('Actitud',arr(form.actitud))}${has(form.mood)?`<div class="field"><span class="fl">Ánimo</span><span class="fv"><em>"${form.mood}"</em></span></div>`:''}${f('Afecto',form.afecto)}${f('Pensamiento',arr(form.pensamiento))}${f('Orientación',arr(form.orientacion))}${has(form.mse_notes)?`<div class="narr">${form.mse_notes}</div>`:''}</div>
    <div class="sec">${sh(4,'GAF')}<div class="gaf-row"><div class="gaf-num">${form.gaf_score}</div><div style="flex:1"><div class="gaf-lbl">${gLabel(form.gaf_score)}</div><div class="gaf-bar"></div><div class="gaf-sc"><span>1</span><span>25</span><span>50</span><span>75</span><span>100</span></div></div></div></div>
    <div class="sec">${sh(5,'Evaluación de Riesgo')}<div class="risk-row"><div class="risk-box" style="background:${riskBgMap[rs]||'#f0f0f0'};color:${riskColor[rs]||'#333'}"><div class="risk-lbl">Suicida</div><div class="risk-val">${rs}</div></div><div class="risk-box" style="background:${riskBgMap[rh]||'#f0f0f0'};color:${riskColor[rh]||'#333'}"><div class="risk-lbl">Homicida</div><div class="risk-val">${rh}</div></div></div>${has(form.safety_plan)?`<div class="narr">${form.safety_plan}</div>`:''}</div>
  </div>
  <div>
    <div class="sec">${sh(6,'Contenido e Intervenciones')}${has(form.session_topics)?`<div class="narr">${form.session_topics}</div>`:''}${arr(form.tecnicas)?`<div class="chips">${chips(arr(form.tecnicas))}</div>`:''}${has(form.resp_interv)?`<div class="narr">${form.resp_interv}</div>`:''}</div>
    <div class="sec">${sh(7,'Progreso y Plan')}${has(form.progreso)?`<div class="chips"><span class="chip chip-b">${form.progreso}</span></div>`:''}${arr(form.cambios)?`<div class="chips">${arr(form.cambios).split(' · ').map(t=>`<span class="chip">${t}</span>`).join('')}</div>`:''}${has(form.homework)?`<div class="narr">${form.homework}</div>`:''}${f('Próxima cita',form.next_appt)}${f('Frecuencia',form.frequency)}</div>
    ${has(form.extra_notes)?`<div class="sec">${sh(8,'Notas Adicionales')}<div class="narr">${form.extra_notes}</div></div>`:''}
  </div>
  </div>

  <div class="sig-wrap">
    <div><div class="sig-line">${form.signed_by||form.clinician||'—'}</div><div class="sig-sub">Clínico · Nombre · Credencial · Licencia</div></div>
    <div><div class="sig-line">${form.enc_date||'—'}</div><div class="sig-sub">Fecha de la nota</div></div>
  </div>
  <div class="cert"><strong>Certificación:</strong> El clínico firmante certifica que la información es correcta, completa y fue documentada de forma contemporánea al servicio, en cumplimiento con HIPAA y la Ley Núm. 408 de Puerto Rico.</div>
  <div class="footer">Caribbean Psychology Wellness Center · Nota de Progreso Clínico · Confidencial – HIPAA · ${new Date().toLocaleDateString('es-PR')}</div>
  </body></html>`
}
